#include <iostream>
using namespace std;
struct Node { int data; Node* left; Node* right; Node(int v) : data(v), left(nullptr), right(nullptr) {} };
Node* insert(Node* root, int k) { if (!root) return new Node(k); if (k < root->data) root->left = insert(root->left, k); else if (k > root->data) root->right = insert(root->right, k); return root; }
Node* search(Node* root, int k) { if (!root) return nullptr; if (k == root->data) return root; if (k < root->data) return search(root->left, k); return search(root->right, k); }
Node* minNode(Node* r) { while (r && r->left) r = r->left; return r; }
Node* del(Node* root, int k) { if (!root) return nullptr; if (k < root->data) root->left = del(root->left, k); else if (k > root->data) root->right = del(root->right, k); else { if (!root->left && !root->right) { delete root; return nullptr; } if (!root->left) { Node* t = root->right; delete root; return t; } if (!root->right) { Node* t = root->left; delete root; return t; } Node* s = minNode(root->right); root->data = s->data; root->right = del(root->right, s->data); } return root; }
int main() { Node* root = nullptr; int n; cout << "Nodes: "; cin >> n; for (int i = 0; i < n; i++) { int v; cin >> v; root = insert(root, v); } int dk; cout << "Delete: "; cin >> dk; root = del(root, dk); int sk; cout << "Search: "; cin >> sk; cout << (search(root, sk) ? "Found" : "Not Found") << endl; return 0; }